  summary = 'This course introduces students to the essential habits of reporting and writing accurate, clear, fair, deadline-ready news. Students learn to identify news, gather verified information, interview sources, write leads, use attribution, apply AP style, cover basic events, and file clean copy under time pressure.',
  data = $nwr1json${"slug": "news-writing-and-reporting-i", "title": "News Writing and Reporting I", "description": "This course introduces students to the essential habits of reporting and writing accurate, clear, fair, deadline-ready news. Students learn to identify news, gather verified information, interview sources, write leads, use attribution, apply AP style, cover basic events, and file clean copy under time pressure.", "topics": [{"id": "19d4a0dd-84f0-4372-9020-7384bb46fa57", "type": "topic", "title": "News Values and Editorial Judgment", "description": "Students begin by learning how journalists decide what is news, why it matters, and how to serve readers without confusing attention with public value.", "children": [{"id": "7731213c-54a9-48b7-8803-848927e51530", "type": "subtopic", "title": "Core news values", "children": [{"id": "d99b1d5b-322b-4b39-b372-64a2a3ef4a90", "type": "concept", "title": "impact"}, {"id": "739d24b7-2a32-488e-8789-43397b53c3da", "type": "concept", "title": "timeliness"}, {"id": "e41a3e40-09c1-4651-bd55-7101cf89be05", "type": "concept", "title": "proximity"}, {"id": "020a56cb-be1b-495e-8ca8-5bd4644ea260", "type": "concept", "title": "conflict"}, {"id": "a34323bf-e9dd-474b-a94a-e1a7b6155b94", "type": "concept", "title": "prominence"}], "description": "Students learn the classic criteria used to identify reportable events and shape story focus."}, {"id": "3688fec9-6eb0-459f-b623-0d2ceaa6532e", "type": "subtopic", "title": "Public-service judgment", "children": [{"id": "b685d3b2-557a-4e87-8c63-c012b52dcc3b", "type": "concept", "title": "community relevance"}, {"id": "d212fc45-2e12-4dcf-9dd7-66f9dc0a4f62", "type": "concept", "title": "accountability"}, {"id": "0172bf52-2724-4404-b67b-3079b1eb2284", "type": "concept", "title": "reader usefulness"}], "description": "This subtopic connects story choice to civic information needs rather than novelty alone."}, {"id": "1026c7cc-3ccd-4849-9580-59e8ebcca1b4", "type": "subtopic", "title": "Angle and focus", "children": [{"id": "4fa00dcc-3a32-4638-8be0-8ea50d0bfc9a", "type": "concept", "title": "central question"}, {"id": "6c94d980-529a-4114-a82c-75a1b6f58432", "type": "concept", "title": "scope"}, {"id": "10ada804-79b4-49e4-82b3-6b6c678b6722", "type": "concept", "title": "reader takeaway"}], "description": "Students practice narrowing broad events into clear, reportable story angles."}]}, {"id": "6b11ee46-8bdb-4842-a87b-cd0d6bf32478", "type": "topic", "title": "Reporting Mindset and Observation", "description": "Before students write news, they need to learn how reporters notice, listen, verify, and gather detail in the field.", "children": [{"id": "d87b0088-33b9-4d6a-bcc3-3aee298ffd86", "type": "subtopic", "title": "Reporter habits", "children": [{"id": "d6c59d04-6976-4278-88da-e5c7c7d5cfb5", "type": "concept", "title": "pre-reporting"}, {"id": "1387ad8a-bab2-4b50-aa61-e3326b7d9032", "type": "concept", "title": "field notes"}, {"id": "6ed7d246-f84b-4777-9621-5b8b7602a2c3", "type": "concept", "title": "follow-up questions"}], "description": "Students build habits of curiosity, skepticism, preparation, and disciplined note-taking."}, {"id": "c74d34c7-c1a1-4765-8e34-d44742b4572d", "type": "subtopic", "title": "Observation as evidence", "children": [{"id": "60bf9cb7-8312-41a8-8005-4e6909615201", "type": "concept", "title": "sensory detail"}, {"id": "7bd513ad-df9f-433f-9b7e-a00f7aa05e50", "type": "concept", "title": "scene description"}, {"id": "db7ff697-fe93-49e7-aec1-95ca685c99ee", "type": "concept", "title": "fact versus inference"}], "description": "The unit teaches students to separate what they saw from what they inferred."}, {"id": "95ddd599-0dd8-4211-974c-120472291253", "type": "subtopic", "title": "Basic reporting plan", "children": [{"id": "54e9a0fb-3cfd-44f7-9dab-8c442710e8ad", "type": "concept", "title": "what is known"}, {"id": "f98d187e-cfc2-4603-b2a1-2ac36f42f32e", "type": "concept", "title": "what is missing"}, {"id": "a85d1926-1822-437f-a479-